-- 【网关验证】浏览器页面测试用户（2026-11-19）：不真发邮件；密码由用户自己用 set_test_staff_password.py 设；免二次验证、不强制改密
SELECT s.staff_no, s.username, s.roles, s.status, s.second_factor_exempt, s.must_change_password, m.role_code FROM sys_ops_staff s LEFT JOIN sys_role_member m ON m.subject_no=s.staff_no WHERE s.staff_no LIKE 'ST-V2UI-%';

